<main class="mx-auto max-w-7xl px-4 py-9 pb-28 sm:px-6 lg:px-8 md:pb-12">
  <div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-[10px] font-black uppercase tracking-[.2em] text-violet-300">The standings</p><h1 class="mt-2 text-3xl font-black"><?= $tournament ? h($tournament['title']) : 'Leaderboards' ?></h1><p class="mt-2 text-sm text-slate-400"><?= $tournament ? 'Match results: ' . h(ucfirst($tournament['results_status'])) : 'Choose a tournament to see its calculated standings.' ?></p></div><?php if ($tournament): ?><a class="rounded-xl border border-white/10 px-4 py-3 text-xs font-bold hover:bg-white/[.05]" href="<?= h(app_url('index.php?page=tournament&id='.(int)$tournament['id'])) ?>">Match details</a><?php endif; ?></div>
  <?php if (!$tournament): ?>
    <div class="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><?php foreach ($availableTournaments as $item): ?><a class="glass-card card-hover rounded-2xl p-5" href="<?= h(app_url('index.php?page=leaderboard&id='.(int)$item['id'])) ?>"><span class="badge badge-soon"><?= h(strtoupper($item['mode'])) ?></span><h2 class="mt-4 font-black"><?= h($item['title']) ?></h2><p class="mt-2 text-xs text-slate-500"><?= h(ucfirst($item['results_status'])) ?> results</p></a><?php endforeach; ?></div>
    <?php if (!$availableTournaments): ?><div class="glass-card mt-6 rounded-2xl p-10 text-center text-sm text-slate-400">No tournament results have been published yet.</div><?php endif; ?>
  <?php else: ?>
    <?php if (!empty($matchNotes)): ?>
      <aside class="mt-5 rounded-2xl border border-amber-300/25 bg-gradient-to-br from-amber-300/[.14] to-orange-400/[.06] p-5 shadow-lg shadow-amber-950/10" aria-label="Match notes">
        <div class="flex items-center gap-3"><span class="grid h-10 w-10 place-items-center rounded-xl bg-amber-300/15 text-amber-200"><i class="fa-solid fa-note-sticky" aria-hidden="true"></i></span><div><p class="text-[10px] font-black uppercase tracking-[.18em] text-amber-200">Admin update</p><h2 class="mt-1 text-lg font-black">Match notes</h2></div></div>
        <div class="mt-4 grid gap-3 sm:grid-cols-2"><?php foreach ($matchNotes as $matchNote): ?><article class="rounded-xl border border-amber-200/10 bg-black/20 p-4"><p class="text-[10px] font-black uppercase tracking-widest text-amber-200">Match <?= h($matchNote['match_number']) ?></p><p class="mt-2 whitespace-pre-line text-sm font-semibold leading-6 text-white"><?= h($matchNote['note']) ?></p></article><?php endforeach; ?></div>
      </aside>
    <?php endif; ?>
