      <div class="flex flex-wrap items-center justify-between gap-3 border-b border-white/[.08] px-5 py-4"><div><h2 class="font-black">Match leaderboard</h2><p class="mt-1 text-[10px] text-slate-500">Ranked by configured tie-breakers · <?= h(count($rows)) ?> entries</p></div><span class="badge <?= $tournament['results_status']==='final'?'badge-open':'badge-soon' ?>"><?= h(strtoupper($tournament['results_status'])) ?></span></div>
      <?php if (!$rows): ?><p class="p-8 text-center text-sm text-slate-500">No results have been entered for this tournament.</p><?php else: ?><div class="table-wrap"><table class="w-full text-left text-xs"><thead class="bg-black/20 text-[10px] uppercase tracking-wider text-slate-500"><tr><th class="px-4 py-4">Rank</th><th class="px-4 py-4">Player / team</th><th class="px-4 py-4">Matches</th><th class="px-4 py-4">Kills</th><th class="px-4 py-4">Placement pts</th><th class="px-4 py-4">Kill pts</th><th class="px-4 py-4">Bonuses</th><th class="px-4 py-4">Penalties</th><th class="px-4 py-4">Total</th></tr></thead><tbody class="divide-y divide-white/[.07]"><?php foreach ($rows as $row): ?><tr class="<?= (int)$row['position']===1?'bg-violet-500/[.06]':'' ?>"><td class="px-4 py-4"><span class="grid h-8 w-8 place-items-center rounded-lg <?= (int)$row['position']===1?'bg-amber-300/10 text-amber-200':'bg-white/[.05] text-slate-300' ?> font-black"><?= h($row['position']) ?></span></td><td class="px-4 py-4"><p class="font-black"><?= h($row['display_name']) ?></p><?php if($row['matches_played']): ?><p class="mt-1 text-[10px] text-slate-500">Best placement #<?= h($row['best_rank'] ?? '—') ?></p><?php endif; ?></td><td class="px-4 py-4"><?= h($row['matches_played']) ?></td><td class="px-4 py-4 font-bold"><?= h($row['total_kills']) ?></td><td class="px-4 py-4"><?= h($row['placement_points']) ?></td><td class="px-4 py-4"><?= h($row['kill_points']) ?></td><td class="px-4 py-4 text-neon-400"><?= h($row['bonus_points']) ?></td><td class="px-4 py-4 text-rose-300">−<?= h($row['penalty_points']) ?></td><td class="px-4 py-4 text-base font-black text-violet-200"><?= h($row['total_points']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
      <p class="border-t border-white/[.08] px-5 py-3 text-[10px] text-slate-500">Scores are computed from results entered or imported by tournament admins. Victory Yudh does not retrieve live Free Fire match data.</p>
